import original from "../../public/model/original/hotspots.json";
import warm from "../../public/model/hotspots.json";
import { MODEL_THEME, type RoomKey } from "../data/portfolio";

// Everything here is generated by model/export_web_layers.py.
// The warm model lives in public/model; the original clay model is kept in
// public/model/original. MODEL_THEME in app/data/portfolio.ts picks one.
export type Spot = { polygon: number[][]; focus: number[]; plan: number[][] };

const themes = {
  warm: { folder: "/model", data: warm, ground: ["#f4e1dc", "#f8ece6"] },
  original: { folder: "/model/original", data: original, ground: ["#efe4d8", "#f3ebe2"] },
};
const theme = themes[MODEL_THEME];

export const model = {
  version: theme.data.version,
  width: theme.data.width,
  height: theme.data.height,
  plinthAspect: theme.data.plinthAspect,
  spots: theme.data.buildings as Record<RoomKey, Spot>,
  // Homepage ground behind the model: top of the gradient, then 70% down.
  ground: theme.ground,
};

// Cache-buster: changes on every Blender export, so visitors always get fresh renders.
export const modelSrc = (file: string) => `${theme.folder}/${file}?v=${model.version}`;
